package com.honorablemobile

import org.junit.Assert.*
import org.junit.Test

class VideoAuthoringToolsTest {
    private val clip=VideoSegment(0,4000,volume=.8f,title="Keep",captions=listOf(VideoCaption(500,1000,"First words"),VideoCaption(1500,2200,"Second phrase")),captionSourceUri="content://subtitles/original")
    @Test fun intervalRemovalClosesGapAndPreservesRemainingProperties(){val out=VideoAuthoringTools.removeInterval(listOf(clip),0,1000,2000);assertEquals(listOf(0L to 1000L,2000L to 4000L),out.map{it.startMs to it.endMs});assertEquals(3000L,out.sumOf{it.durationMs});assertTrue(out.all{it.volume==clip.volume&&it.title==clip.title&&it.captionSourceUri==clip.captionSourceUri})}
    @Test fun completeClipRemovalRequiresAnotherClip(){assertTrue(runCatching{VideoAuthoringTools.removeInterval(listOf(clip),0,0,4000)}.isFailure);assertEquals(listOf(clip),VideoAuthoringTools.removeInterval(listOf(clip,clip),0,0,4000))}
    @Test fun invalidIntervalsAndTinyRemaindersDoNotChangeInput(){val before=listOf(clip);for((a,b) in listOf(-1L to 1000L,0L to 5000L,50L to 1000L,2000L to 1000L))assertTrue(runCatching{VideoAuthoringTools.removeInterval(before,0,a,b)}.isFailure);assertEquals(clip,before.single())}
    @Test fun captionCutsKeepOnlyCaptionedRangesWithMergedHandles(){val out=VideoAuthoringTools.captionCut(listOf(clip),0,300);assertEquals(listOf(200L to 2500L),out.map{it.startMs to it.endMs});assertEquals(clip.captions,out.single().captions)}
    @Test fun captionCutsRejectAbsentOrUnsupportedShortCues(){assertTrue(runCatching{VideoAuthoringTools.captionCut(listOf(clip.copy(captions=emptyList())),0,0)}.isFailure);assertTrue(runCatching{VideoAuthoringTools.captionCut(listOf(clip.copy(captions=listOf(VideoCaption(0,20,"Short")))),0,0)}.isFailure)}
    @Test fun beatGridAccountsForSpeedAndCoversEverySourceMillisecond(){val c=clip.copy(speed=2f);val out=VideoAuthoringTools.beatGrid(listOf(c),120);assertEquals(4,out.size);assertEquals(listOf(0L,1000L,2000L,3000L),out.map{it.startMs});assertEquals(c.endMs,out.last().endMs);assertTrue(out.zipWithNext().all{it.first.endMs==it.second.startMs});assertTrue(out.all{it.speed==2f})}
    @Test fun beatGridContinuesAcrossExistingClipBoundaries(){val out=VideoAuthoringTools.beatGrid(listOf(VideoSegment(0,750),VideoSegment(0,750,sourceId="other")),120);assertEquals(listOf(0L to 500L,500L to 750L,0L to 250L,250L to 750L),out.map{it.startMs to it.endMs})}
    @Test fun beatGridRefusesUnboundedProjectsAndInvalidTempos(){assertTrue(runCatching{VideoAuthoringTools.beatGrid(listOf(VideoSegment(0,1_000_000)),240)}.isFailure);assertTrue(runCatching{VideoAuthoringTools.beatGrid(listOf(clip),0)}.isFailure)}
    @Test fun steppedRampPreservesSourceCoverageAndUsesSupportedSpeeds(){val out=VideoAuthoringTools.speedRamp(listOf(clip),0,true);assertEquals(listOf(.5f,1f,1.5f,2f),out.map{it.speed});assertEquals(4000L,out.sumOf{it.endMs-it.startMs});assertEquals(listOf(2f,1.5f,1f,.5f),VideoAuthoringTools.speedRamp(listOf(clip),0,false).map{it.speed});assertTrue(out.all{it.title==clip.title&&it.volume==clip.volume})}
    @Test fun rampRejectsShortFootageAndClipOverflow(){assertTrue(runCatching{VideoAuthoringTools.speedRamp(listOf(VideoSegment(0,799)),0,true)}.isFailure);assertTrue(runCatching{VideoAuthoringTools.speedRamp(List(1000){clip},0,true)}.isFailure)}
    @Test fun interleavingKeepsEveryClipAndOrderWithinEachSource(){val input=listOf(clip.copy(title="A1"),clip.copy(title="A2"),clip.copy(sourceId="b",title="B1"),clip.copy(sourceId="b",title="B2"),clip.copy(sourceId="b",title="B3"));val out=VideoAuthoringTools.interleaveSources(input);assertEquals(listOf("A1","B1","A2","B2","B3"),out.map{it.title});assertEquals(input.toSet(),out.toSet());assertTrue(runCatching{VideoAuthoringTools.interleaveSources(listOf(clip))}.isFailure)}
    @Test fun wordCaptionsKeepUnicodeWordsAndOriginalTiming(){val c=clip.copy(captions=listOf(VideoCaption(500,3500,"Hello 😀 world")));val out=VideoAuthoringTools.wordCaptions(listOf(c),0,1).single();assertEquals(listOf("Hello","😀","world"),out.captions.map{it.text});assertEquals(500L,out.captions.first().startMs);assertEquals(3500L,out.captions.last().endMs);assertTrue(out.captions.zipWithNext().all{it.first.endMs==it.second.startMs});assertNull(out.captionSourceUri)}
    @Test fun wordCaptionLimitsFailBeforeProjectMutation(){val c=clip.copy(endMs=40000,captions=List(200){VideoCaption(it*200L,it*200L+180,"two words")});assertTrue(runCatching{VideoAuthoringTools.wordCaptions(listOf(c),0,1)}.isFailure);assertEquals(200,c.captions.size)}
    @Test fun captionMergingRespectsGapDurationAndTextBounds(){val c=clip.copy(captions=listOf(VideoCaption(0,500,"First"),VideoCaption(600,1000,"next"),VideoCaption(3000,3500,"Later")));val out=VideoAuthoringTools.mergeCaptions(listOf(c),0,150).single().captions;assertEquals(2,out.size);assertEquals(VideoCaption(0,1000,"First next"),out.first());assertEquals("Later",out.last().text)}
    @Test fun timecodesUseOriginalSourceTimeWithPlaybackSpacing(){val c=VideoSegment(1000,5000,speed=2f);val out=VideoAuthoringTools.sourceTimecodes(listOf(c),0,1000).single().captions;assertEquals(listOf(1000L,3000L),out.map{it.startMs});assertEquals("TC 00:00:01.000",out.first().text);assertEquals(5000L,out.last().endMs)}
    @Test fun timecodesAreBounded(){assertTrue(runCatching{VideoAuthoringTools.sourceTimecodes(listOf(VideoSegment(0,1_000_000)),0,1000)}.isFailure)}
    @Test fun captionDuckingOnlyChangesCaptionedOriginalAudio(){val c=clip.copy(endMs=1000,captions=listOf(VideoCaption(200,500,"Words")));val out=VideoAuthoringTools.captionDucking(listOf(c),0,.25f);assertEquals(listOf(0L to 200L,200L to 500L,500L to 1000L),out.map{it.startMs to it.endMs});assertEquals(listOf(.8f,.2f,.8f),out.map{it.volume});assertTrue(out.all{it.captionSourceUri==clip.captionSourceUri})}
    @Test fun duckingRejectsFadesInsteadOfCreatingRepeatedEdgeFades(){assertTrue(runCatching{VideoAuthoringTools.captionDucking(listOf(clip.copy(audioFade=true)),0,.25f)}.isFailure);assertTrue(runCatching{VideoAuthoringTools.captionDucking(listOf(clip),0,Float.NaN)}.isFailure)}
    @Test fun storyboardTitlesRequireExactlyOneValidLinePerClip(){val out=VideoAuthoringTools.storyboardTitles(listOf(clip,clip),"Opening\nClosing\n");assertEquals(listOf("Opening","Closing"),out.map{it.title});assertTrue(runCatching{VideoAuthoringTools.storyboardTitles(listOf(clip,clip),"Only one")}.isFailure);assertTrue(runCatching{VideoAuthoringTools.storyboardTitles(listOf(clip),"x".repeat(121))}.isFailure)}
    @Test fun entireAuthoringProposalIsOneUndoAndKeepsSoundtrack(){val project=VideoEditProject(4000);val music=VideoSoundtrack("content://music/original",10000,.3f);project.setSoundtrack(music);val before=project.segments;project.applyDraft(VideoAuthoringTools.speedRamp(before,0,true),soundtrack=music);assertEquals(4,project.segments.size);assertEquals(music,project.soundtrack);assertTrue(project.undo());assertEquals(before,project.segments);assertEquals(music,project.soundtrack);assertTrue(project.redo());assertEquals(4,project.segments.size);assertEquals(music,project.soundtrack)}
}
